// TOTAL HQ — worker v1
// Parent hub for the HQ family. Serves the board of properties and the shared
// registry (/registry.json) that every child site can read instead of hardcoding.

const REGISTRY = {
  updated: "2026-11-21",
  parent: { name: "Total HQ", url: "https://total-hq.com" },
  boards: [
    { key:"mlb", league:"MLB", name:"Moonshot HQ",  word:"Moonshot",  icon:"⚾", cadence:"Daily",  status:"live", url:"https://moonshot-hq.com",  accent:"#FFC24B" },
    { key:"nfl", league:"NFL", name:"Touchdown HQ", word:"Touchdown", icon:"🏈", cadence:"Weekly", status:"live", url:"https://touchdown-hq.com", accent:"#FF4D3D" },
    { key:"nhl", league:"NHL", name:"Slapshot HQ",  word:"Slapshot",  icon:"🏒", cadence:"Daily",  status:"live", url:"https://slapshot-hq.com",  accent:"#7CC8FF" },
    { key:"nba", league:"NBA", name:"Slam HQ",      word:"Slam",      icon:"🏀", cadence:"Daily",  status:"live", url:"https://slam-hq.com",      accent:"#FF8A3D" },
    { key:"soc", league:"SOC", name:"Futbol HQ",    word:"Futbol",    icon:"⚽", cadence:"Daily",  status:"live", url:"https://futbol-hq.com",    accent:"#4ADE80" }
  ]
};

const OG_PNG = "";
const TOUCH_ICON = "";
const FAVICON = "";
function pngResponse(b64data) {
  const bin = atob(b64data);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, { headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=86400" } });
}
function serveAsset(path) {
  if (path === "/og.png") return pngResponse(OG_PNG);
  if (path === "/apple-touch-icon.png") return pngResponse(TOUCH_ICON);
  if (path === "/favicon.png" || path === "/favicon.ico") return pngResponse(FAVICON);
  return null;
}

// ---------- board builds on schedule ----------
// GitHub's scheduler often runs late or not at all, so this Worker's cron starts the builds instead.
// Times are UTC, matching each workflow's own schedule; the cron fires every 10 minutes, so each
// time is caught by the tick in its 10-minute window. The token (Actions: write on hq-data only) is a secret.
const BUILDS = [
  // hourly, plus half past while a match has kicked off and its player stats aren't in yet
  { wf: "soccer.yml", at: m => m.mi === 20 || (m.mi === 50 && m.socPending) },
  // 6:10 UTC is just after midnight Central: tomorrow's board becomes today's and the next day's is built
  { wf: "nhl.yml", at: m => [[6, 10], [12, 10], [16, 10], [14, 30], [19, 30], [22, 30]].some(([h, mi]) => m.h === h && m.mi === mi) },
  { wf: "nba.yml", at: m => [[6, 10], [13, 10], [21, 40], [15, 30], [18, 30], [23, 30]].some(([h, mi]) => m.h === h && m.mi === mi) },
  { wf: "nfl.yml", at: m => [[11, 10], [21, 10], [14, 30], [19, 30]].some(([h, mi]) => m.h === h && m.mi === mi) || (m.dow === 0 && m.h === 16 && m.mi === 0) },
];
// a soccer match that started in the last six hours and isn't marked finished on the board yet
async function socPending(when) {
  try {
    const bd = await (await fetch(RAW + "soccer/board.json", { cf: { cacheTtl: 120, cacheEverything: true } })).json();
    return (bd.games || []).some(g => { const t = Date.parse(g.t); return !g.fin && t <= when && when - t < 6 * 3600e3; });
  } catch (e) { return false; }
}
async function startBuilds(when, env) {
  if (!env || !env.GH_DISPATCH) return;
  const d = new Date(when), m = { h: d.getUTCHours(), mi: Math.floor(d.getUTCMinutes() / 10) * 10, dow: d.getUTCDay() };
  if (m.mi === 50) m.socPending = await socPending(when);
  await Promise.all(BUILDS.filter(b => b.at(m)).map(b => fetch("https://api.github.com/repos/mattgrnr/hq-data/actions/workflows/" + b.wf + "/dispatches", {
    method: "POST",
    headers: { Authorization: "Bearer " + env.GH_DISPATCH, Accept: "application/vnd.github+json", "User-Agent": "total-hq", "Content-Type": "application/json" },
    body: JSON.stringify({ ref: "main" }),
  }).catch(() => {})));
}

const HQ_APP = {
  async scheduled(event, env, ctx) {
    ctx.waitUntil(startBuilds(event.scheduledTime, env));
  },
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    const asset = serveAsset(path);
    if (asset) return asset;

    if (path === "/slate") return slate(env, request);
    if (path === "/betlink") return betLink(url, request, env);
    if (path === "/p") return saveSlip(request, env, url);
    if (path === "/best") return best();
    if (path === "/guide") return new Response(GUIDE, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "public, max-age=300" } });
    if (path === "/track") return track(request);
    const sm = /^\/p\/([A-Za-z0-9]{7})$/.exec(path);
    if (sm) return showSlip(sm[1], env, url);

    if (path === "/registry.json") {
      return new Response(JSON.stringify(REGISTRY), {
        headers: {
          "Content-Type": "application/json; charset=utf-8",
          "Cache-Control": "public, max-age=3600",
          "Access-Control-Allow-Origin": "*"
        }
      });
    }

    return new Response(page(url.origin, null), {
      headers: { "Content-Type": "text/html; charset=utf-8" }
    });
  }
};

const RAW = "https://raw.githubusercontent.com/mattgrnr/hq-data/main/";

