const SPORT_DIR = { nhl: "nhl", nba: "nba", nfl: "nfl", soc: "soccer" };

// One tap from a parlay to a sportsbook's bet slip with every leg loaded. PropLine builds the link
// from its own bet ids (FanDuel's slip needs market ids the odds feed doesn't carry); the key is a Worker secret.
const SLIP_BOOKS = { DK: "https://sportsbook.draftkings.com", FD: "https://sportsbook.fanduel.com", FAN: "https://sportsbook.fanatics.com" };
const HQ_REF = /^https:\/\/(([a-z0-9-]+\.)?(total|moonshot|touchdown|slapshot|slam|futbol)-hq\.com|[a-z0-9-]+-(total|moonshot|touchdown|slapshot|slam|futbol)-hq\.wehttam30\.workers\.dev)\//;
async function betLink(url, request, env) {
  const bk = url.searchParams.get("bk") || "", ids = url.searchParams.get("ids") || "";
  const home = SLIP_BOOKS[bk];
  if (!home) return Response.redirect("https://total-hq.com/", 302);
  if (!/^\d{4,20}(,\d{4,20}){0,11}$/.test(ids)) return Response.redirect(home, 302);
  const origin = request.headers.get("Origin") || "";
  const fromHQ = HQ_REF.test(request.headers.get("Referer") || "") || HQ_REF.test(origin + "/");
  const json = url.searchParams.get("json") === "1";
  const cors = HQ_REF.test(origin + "/") ? { "Access-Control-Allow-Origin": origin, "Vary": "Origin" } : {};
  if (!fromHQ) return json ? new Response("{}", { status: 403, headers: { "Content-Type": "application/json", ...cors } }) : Response.redirect(home, 302);
  const cache = caches.default, key = new Request("https://total-hq.com/betlink?bk=" + bk + "&ids=" + ids);
  const hit = await cache.match(key);
  if (hit) {
    if (!json) return hit;
    return new Response(JSON.stringify({ link: hit.headers.get("Location") }), { headers: { "Content-Type": "application/json", "Cache-Control": "no-store", ...cors } });
  }
  let to = home;
  try {
    if (env && env.PROPLINE_KEY) {
      const res = await fetch("https://api.prop-line.com/v1/bet-links/parlay?outcome_ids=" + ids + "&apiKey=" + encodeURIComponent(env.PROPLINE_KEY));
      if (res.ok) { const d = await res.json(); if (d && d.bet_link) to = d.bet_link; }
    }
  } catch (e) {}
  const out = new Response(null, { status: 302, headers: { Location: to, "Cache-Control": to === home ? "no-store" : "public, max-age=600" } });
  if (to !== home) await cache.put(key, out.clone());
  if (json) return new Response(JSON.stringify({ link: to === home ? null : to }), { headers: { "Content-Type": "application/json", "Cache-Control": "no-store", ...cors } });
  return out;
}

// ---------- shared betslips: a short link to a parlay, kept until two days after its last game ----------
function slipTtl(legs) {
  const last = Math.max(0, ...legs.map(l => l.t || 0));
  const ttl = Math.round(((last || Date.now()) + 2 * 86400e3 - Date.now()) / 1000);
  return Math.min(10 * 86400, Math.max(86400, ttl));      // at least a day, at most ten (a long NFL week)
}
function page(origin, shared, meta) {
  let h = HTML.split("__ORIGIN__").join(origin);
  h = h.replace("var SHARED = null;", "var SHARED = " + JSON.stringify(shared).replace(/</g, "\\u003c") + ";");
  if (meta) {
    const e = s => String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
    h = h.replace("<title>TOTAL HQ — Every Sport, Scored 0–100</title>", "<title>" + e(meta.title) + " · Total HQ</title>")
      .replace('<meta property="og:title" content="TOTAL HQ — Every Sport, Scored 0–100">', '<meta property="og:title" content="' + e(meta.title) + '">')
      .replace('<meta property="og:description" content="One board per sport. Every player on the slate, scored 0 to 100.">', '<meta property="og:description" content="' + e(meta.desc) + '">')
      .replace('<meta property="og:url" content="' + origin + '">', '<meta property="og:url" content="' + origin + "/p/" + meta.id + '">');
  }
  return h;
}
async function saveSlip(request, env, url) {
  const origin = request.headers.get("Origin") || "";
  const cors = HQ_REF.test(origin + "/") ? { "Access-Control-Allow-Origin": origin, "Vary": "Origin" } : null;
  const out = (o, status) => new Response(JSON.stringify(o), { status: status || 200, headers: { "Content-Type": "application/json", "Cache-Control": "no-store", ...(cors || {}) } });
  if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: { ...(cors || {}), "Access-Control-Allow-Methods": "POST", "Access-Control-Allow-Headers": "Content-Type" } });
  if (request.method !== "POST" || !cors) return out({ error: "forbidden" }, 403);
  if (!env || !env.SLIPS) return out({ error: "storage not set up" }, 503);
  const body = await request.text();
  if (body.length > 40000) return out({ error: "too big" }, 413);
  let d;
  try { d = JSON.parse(body); } catch (e) { return out({ error: "bad request" }, 400); }
  const str = (v, n) => typeof v === "string" ? v.slice(0, n) : undefined;
  const num = v => typeof v === "number" && isFinite(v) ? v : undefined;
  const map = (o, f) => { const r = {}; if (o && typeof o === "object") for (const k of Object.keys(o).slice(0, 12)) if (/^[A-Z]{2,4}$/.test(k)) { const v = f(o[k]); if (v !== undefined) r[k] = v; } return r; };
  const legs = (Array.isArray(d && d.legs) ? d.legs : []).slice(0, 15).map(l => ({
    i: str(l.i, 240), s: str(l.s, 20), g: str(l.g, 80), t: num(l.t), l: str(l.l, 120), p: num(l.p), b: str(l.b, 4),
    a: map(l.a, num), u: map(l.u, v => typeof v === "string" && /^(https:\/\/|hardrock:\/\/)/.test(v) ? v.slice(0, 300) : undefined),
    x: map(l.x, v => typeof v === "string" || typeof v === "number" ? String(v).slice(0, 80) : undefined), o: num(l.o), k: num(l.k),
    q: l.q && typeof l.q === "object" ? { sp: str(l.q.sp, 4), gid: str(l.q.gid, 40), pid: str(l.q.pid, 20), st: str(l.q.st, 4), k: num(l.q.k), wk: str(l.q.wk, 10), h: str(l.q.h, 40), a: str(l.q.a, 40), lbl: str(l.q.lbl, 80) } : undefined,
  })).filter(l => l.i && l.l);
  if (!legs.length) return out({ error: "no legs" }, 400);
  const abc = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789", r = crypto.getRandomValues(new Uint8Array(7));
  const id = Array.from(r, x => abc[x % abc.length]).join("");
  await env.SLIPS.put(id, JSON.stringify({ legs, bk: str(d.bk, 4) || null, at: Date.now() }), { expirationTtl: slipTtl(legs) });
  return out({ id, url: url.origin + "/p/" + id });
}
async function showSlip(id, env, url) {
  const raw = env && env.SLIPS ? await env.SLIPS.get(id) : null;
  const html = h => new Response(h, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
  if (!raw) return html(page(url.origin, { id, gone: true }));
  const slip = JSON.parse(raw);
  const dec = a => a > 0 ? 1 + a / 100 : 1 + 100 / (-a);
  const amer = d => d >= 2 ? "+" + Math.round((d - 1) * 100) : String(Math.round(-100 / (d - 1)));
  const names = { DK: "DraftKings", FD: "FanDuel", MGM: "BetMGM", CZR: "Caesars", FAN: "Fanatics", ESPN: "ESPN Bet", BR: "BetRivers", HR: "Hard Rock" };
  let best = null;
  for (const bk of new Set(slip.legs.flatMap(l => Object.keys(l.a || {})))) {
    if (!slip.legs.every(l => l.a && l.a[bk] != null)) continue;
    const d = slip.legs.reduce((m, l) => m * dec(l.a[bk]), 1);
    if (bk === slip.bk || !best || (best.bk !== slip.bk && d > best.d)) best = { bk, d };
  }
  const n = slip.legs.length;
  const title = n + "-leg parlay" + (best ? " · " + amer(best.d) + " at " + (names[best.bk] || best.bk) : "");
  const desc = slip.legs.map(l => l.l).join(" · ").slice(0, 190);
  return html(page(url.origin, { id, ...slip }, { id, title, desc }));
}

// ---------- today's best bets across every sport (each board's build saves its own) ----------
const BEST_RAW = RAW;
const BEST_OF = { nhl: ["nhl", "Slapshot"], nba: ["nba", "Slam"], nfl: ["nfl", "Touchdown"], soc: ["soccer", "Futbol"] };
async function best() {
  const now = Date.now(), all = [];
  await Promise.all(Object.values(BEST_OF).map(async ([dir]) => {
    try {
      const res = await fetch(BEST_RAW + dir + "/best.json?v=" + Math.floor(now / 300000), { cf: { cacheTtl: 300, cacheEverything: true } });
      if (!res.ok) return;
      for (const b of (await res.json()).bets || []) if (b.leg && (!b.leg.t || (b.leg.t > now && ctDay(b.leg.t) === ctDay(now)))) all.push(b);
    } catch (e) {}
  }));
  // up to four per sport, dealt out in turns so one busy slate can't fill the list
  const by = {}, out = [];
  all.sort((a, b) => (b.score ?? b.ev) - (a.score ?? a.ev));
  for (const b of all) (by[b.leg.s] = by[b.leg.s] || []).push(b);
  for (let i = 0; i < 4; i++) for (const s of Object.keys(by)) if (by[s][i]) out.push(by[s][i]);
  return new Response(JSON.stringify({ bets: out }), { headers: { "Content-Type": "application/json", "Cache-Control": "public, max-age=120" } });
}

// ---------- following a parlay's legs live ----------
// each leg carries q: { sp, gid, pid, st, k } for a player stat, or { sp, gid, h, a, lbl } for a game result
const NBA_STAT = { points: "PTS", rebounds: "REB", assists: "AST", steals: "STL", blocks: "BLK", PTS: "PTS", REB: "REB", AST: "AST", STL: "STL", BLK: "BLK" };
const COMBO = { PRA: ["PTS", "REB", "AST"], PR: ["PTS", "REB"], PA: ["PTS", "AST"], RA: ["REB", "AST"] };
async function gameNow(sp, gid, wk) {
  const get = async u => (await fetch(u, { cf: { cacheTtl: 15, cacheEverything: true } })).json();
  if (sp === "nhl") {
    const b = await get("https://api-web.nhle.com/v1/gamecenter/" + gid + "/boxscore"), players = {};
    const side = b.playerByGameStats || {};
    for (const t of [side.awayTeam, side.homeTeam]) for (const x of [...((t || {}).forwards || []), ...((t || {}).defense || [])])
      players[x.playerId] = { G: x.goals || 0, A: x.assists || 0, P: x.points != null ? x.points : (x.goals || 0) + (x.assists || 0), S: x.sog || 0 };
    const st = ["LIVE", "CRIT"].includes(b.gameState) ? "live" : ["FINAL", "OFF"].includes(b.gameState) ? "final" : "pre";
    return { st, sc: [(b.homeTeam || {}).score, (b.awayTeam || {}).score], players };
  }
  if (sp === "nba") {
    const b = await get("https://site.api.espn.com/apis/site/v2/sports/basketball/nba/summary?event=" + gid), players = {};
    for (const team of (b.boxscore && b.boxscore.players) || []) for (const grp of team.statistics || []) {
      const names = grp.keys && grp.keys.length ? grp.keys : (grp.labels || []);
      for (const a of grp.athletes || []) {
        if (!a.athlete || !a.stats || !a.stats.length) continue;
        const o = players[a.athlete.id] = players[a.athlete.id] || {};
        names.forEach((k, i) => { const v = a.stats[i]; if (NBA_STAT[k]) o[NBA_STAT[k]] = +v || 0; else if (/^threePointFieldGoalsMade/.test(k) || k === "3PT") o["3PM"] = parseInt(v, 10) || 0; });
      }
    }
    const c = ((b.header || {}).competitions || [])[0] || {}, state = ((c.status || {}).type || {}).state;
    const score = w => +(((c.competitors || []).find(x => x.homeAway === w) || {}).score || 0);
    return { st: state === "in" ? "live" : state === "post" ? "final" : "pre", sc: [score("home"), score("away")], players };
  }
  if (sp === "nfl") {
    const d = await get("https://api.sleeper.app/v1/stats/nfl/regular/" + wk), players = {};
    for (const [id, x] of Object.entries(d || {})) players[id] = { TD: Math.round((+x.rush_td || 0) + (+x.rec_td || 0)), CYD: Math.round(+x.rec_yd || 0),
      RYD: Math.round(+x.rush_yd || 0), REC: Math.round(+x.rec || 0), PYD: Math.round(+x.pass_yd || 0), PTD: Math.round(+x.pass_td || 0) };
    return { st: null, players };
  }
  if (sp === "soc") {
    const bd = await get(RAW + "soccer/board.json?v=" + Math.floor(Date.now() / 300000)), players = {};
    const g = (bd.games || []).find(x => String(x.id) === String(gid)), gi = (bd.games || []).indexOf(g);
    for (const p of bd.players || []) if (p.g === gi) players[p.id] = p.lv || (g && g.fin ? { G: 0, A: 0, GA: 0, T: 0, S: 0 } : null);
    return { st: g && g.fin ? "final" : null, players };
  }
  return null;
}
async function track(request) {
  const ref = request.headers.get("Referer") || request.headers.get("Origin") || "";
  if (!HQ_REF.test(ref.endsWith("/") ? ref : ref + "/") && !/^https:\/\/total-hq\.com\//.test(ref)) return new Response("Forbidden", { status: 403 });
  let qs = [];
  try { qs = (await request.json()).qs || []; } catch (e) {}
  qs = qs.slice(0, 30);
  const games = {};
  for (const q of qs) if (q && q.sp && (q.gid || q.wk)) { const k = q.sp + "|" + (q.sp === "nfl" ? q.wk : q.gid); games[k] = games[k] || gameNow(q.sp, q.gid, q.wk).catch(() => null); }
  const out = await Promise.all(qs.map(async q => {
    if (!q || !q.sp) return null;
    const g = await games[q.sp + "|" + (q.sp === "nfl" ? q.wk : q.gid)];
    if (!g) return null;
    if (q.st) {
      const x = g.players[q.pid];
      const v = !x ? null : COMBO[q.st] ? COMBO[q.st].reduce((a, k) => a + (x[k] || 0), 0) : x[q.st];
      return { st: g.st, v: v == null ? null : v };
    }
    return { st: g.st, sc: g.sc || null };
  }));
  return new Response(JSON.stringify({ r: out }), { headers: { "Content-Type": "application/json", "Cache-Control": "no-store" } });
}

// today's projected games per sport, small enough to load with the page
// the calendar day in Central time, so "today" matches what the boards show
function ctDay(ms) { return new Date(ms).toLocaleDateString("en-CA", { timeZone: "America/Chicago" }); }

// our competitions under PropLine's names, for live soccer scores
const SOC_FEED = { "Premier League": "soccer_epl", "LaLiga": "soccer_la_liga", "Serie A": "soccer_serie_a", "Bundesliga": "soccer_bundesliga",
  "Ligue 1": "soccer_ligue_1", "Champions League": "soccer_uefa_champions_league", "Europa League": "soccer_uefa_europa_league",
  "Conference League": "soccer_uefa_conference_league", "MLS": "soccer_mls", "Liga MX": "soccer_liga_mx", "Saudi Pro League": "soccer_saudi_pro" };
// the same club under two spellings ("Man.City" / "Man City", "Betis" / "Real Betis", "Bodo Glimt" / "Bodø/Glimt")
function clubWords(n) {
  return String(n || "").toLowerCase().replace(/ø/g, "o").replace(/æ/g, "ae").normalize("NFKD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ").split(" ").filter(w => w && !["fc", "cf", "afc", "sc", "ac", "the", "de", "1907"].includes(w))
    .map(w => ({ manchester: "man", utd: "united", lisbon: "cp", munich: "munchen", lafc: "angeles", gladbach: "monchengladbach",
      cologne: "koln", hazm: "hazem", feiha: "fayha", taawon: "taawoun", qadisiyah: "qadsiah" })[w] || w);
}
function sameSide(a, b) {
  const x = clubWords(a), y = clubWords(b);
  if (x.join(" ") === y.join(" ")) return true;
  if ((x.includes("city") !== y.includes("city")) || (x.includes("united") !== y.includes("united") && (x.includes("man") || y.includes("man")))) return false;
  const common = ["real", "atletico", "sporting", "athletic", "borussia", "olympique", "racing", "deportivo", "union", "stade", "club", "city", "united", "man"];
  const pre = w => ["real", "atletico", "athletic", "racing", "deportivo", "sporting"].includes(w);
  const px = x.find(pre), py = y.find(pre);
  if (px && py && px !== py) return false;      // Real Madrid is not Atletico Madrid
  return x.some(w => w.length >= 4 && !common.includes(w) && y.includes(w)) || (x.join(" ").includes(y.join(" ")) || y.join(" ").includes(x.join(" ")));
}

// ESPN's NFL abbreviations where they differ from the board's
const NFL_ESPN = { LA: "LAR", WAS: "WSH" };

async function slate(env, request) {
  const out = {};
  await Promise.all(Object.entries(SPORT_DIR).map(async ([key, dir]) => {
    try {
      const res = await fetch(RAW + dir + "/board.json", { cf: { cacheTtl: 300, cacheEverything: true } });
      if (!res.ok) return;
      const bd = await res.json();
      // today's games (Central time), or the NFL's whole week; finished ones stay until the day is over
      const now = Date.now(), today = ctDay(now);
      const start = g => key === "soc" ? Date.parse(g.t) : g.ko ? g.ko * 1000 : Date.parse(String(g.start).replace("Z", ":00Z"));
      const keep = g => key === "nfl" ? (g.final ? ctDay(start(g)) === today : start(g) < now + 7 * 24 * 3600e3) : ctDay(start(g)) === today;
      const list = (bd.games || []).filter(g => g.proj && keep(g)).map(g => key === "soc"
        ? { h: g.h, a: g.a, k: String(g.id), id: g.id, lg: g.league, t: g.t, win: g.proj.win, hs: g.proj.hs, as: g.proj.as, st: g.fin ? "final" : null, sc: g.sc || null }
        : { h: g.home, a: g.away, k: g.home, id: g.id, t: g.start || (g.ko ? new Date(g.ko * 1000).toISOString() : null), win: g.proj.win, hs: g.proj.hs, as: g.proj.as, st: g.final ? "final" : null, sc: null });
      await scores(key, list, now, env);
      const rank = g => g.st === "final" ? 0 : g.st === "live" ? 1 : 2;      // the day in order: finished, live, still to come
      out[key] = list.sort((x, y) => rank(x) - rank(y) || Date.parse(x.t) - Date.parse(y.t)).map(g => { delete g.id; return g; });
    } catch (e) {}
  }));
  const origin = request ? request.headers.get("Origin") || "" : "";      // the sport sites read it for their Games tab scores
  const cors = HQ_REF.test(origin + "/") ? { "Access-Control-Allow-Origin": origin, "Vary": "Origin" } : {};
  return new Response(JSON.stringify(out), { headers: { "Content-Type": "application/json", "Cache-Control": "public, max-age=60", ...cors } });
}

// live and final scores for games under way, from the same sources bet tracking uses;
// sc is in the order the lane shows the teams (soccer home first, everything else away first)
async function scores(key, list, now, env) {
  const started = list.filter(g => g.t && Date.parse(g.t) <= now);
  if (!started.length) return;
  if (key === "nba" || key === "nhl") {
    await Promise.all(started.map(async g => {
      try {
        const x = await gameNow(key, g.id);
        if (x && x.st) { g.st = x.st; g.sc = x.st === "pre" ? null : [x.sc[1], x.sc[0]]; }
      } catch (e) {}
    }));
  } else if (key === "nfl") {
    try {
      const d = await (await fetch("https://site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard", { cf: { cacheTtl: 30, cacheEverything: true } })).json();
      for (const ev of d.events || []) {
        const c = (ev.competitions || [])[0] || {}, team = w => (c.competitors || []).find(x => x.homeAway === w) || {};
        const g = started.find(x => (NFL_ESPN[x.h] || x.h) === (team("home").team || {}).abbreviation && (NFL_ESPN[x.a] || x.a) === (team("away").team || {}).abbreviation);
        const state = ((c.status || {}).type || {}).state;
        if (g && state && state !== "pre") { g.st = state === "post" ? "final" : "live"; g.sc = [+team("away").score || 0, +team("home").score || 0]; }
      }
    } catch (e) {}
  }
  if (key === "soc" && env && env.PROPLINE_KEY) {
    // PropLine's scores feed, one call per competition on today's slate, shared by everyone for a minute
    const leagues = [...new Set(started.map(g => SOC_FEED[g.lg]).filter(Boolean))];
    const feed = (await Promise.all(leagues.map(async sk => {
      try {
        const r = await fetch("https://api.prop-line.com/v1/sports/" + sk + "/scores?daysFrom=1&apiKey=" + encodeURIComponent(env.PROPLINE_KEY), { cf: { cacheTtl: 60, cacheEverything: true } });
        return r.ok ? await r.json() : [];
      } catch (e) { return []; }
    }))).flat();
    for (const g of started) {
      const x = feed.find(x => Math.abs(Date.parse(x.commence_time) - Date.parse(g.t)) < 15 * 60e3 && sameSide(x.home_team, g.h) && sameSide(x.away_team, g.a));
      if (!x || x.status === "upcoming") continue;
      g.st = x.status === "final" ? "final" : "live";
      if (x.home_score != null) g.sc = [+x.home_score, +x.away_score];
      if (g.st === "live" && x.period) g.clk = String(x.period).slice(0, 8);
    }
  }
  // the board's own word, or kickoff long enough ago that it must be over
  for (const g of started) if (!g.st) g.st = now - Date.parse(g.t) > (key === "soc" ? 2.5 : 4) * 3600e3 ? "final" : "live";
}

